// The article list and both grouped views are generated by Eleventy.
// Only the selector needs JavaScript; without it the alphabetical list works.
for (const root of document.querySelectorAll("[data-article-views]")) {
  const controls = root.querySelector(".app-article-view-controls");
  const buttons = [...root.querySelectorAll("[data-article-view]")];
  const panels = [...root.querySelectorAll("[data-article-panel]")];
  if (!controls || buttons.length !== 3 || panels.length !== 3) continue;

  controls.hidden = false;
  for (const button of buttons) {
    button.addEventListener("click", () => {
      const selected = button.dataset.articleView;
      for (const choice of buttons)
        choice.setAttribute("aria-pressed", String(choice === button));
      for (const panel of panels)
        panel.hidden = panel.dataset.articlePanel !== selected;
    });
  }
}
